package main

import (
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func TestProbeValidID(t *testing.T) {
	if !ValidSessionID("abcd1234-ABCD") {
		t.Fatal("valid id rejected")
	}
	if !ValidSessionID("abc") {
		t.Fatal("fixture id abc must stay valid")
	}
	for _, bad := range []string{"", "a", "has space", "has_underscore", "slash/here", strings.Repeat("a", 65)} {
		if ValidSessionID(bad) {
			t.Fatalf("invalid id %q accepted", bad)
		}
	}

	store := NewStore(time.Minute)
	store.Create("bad id", "u")
	if store.Len() != 0 {
		t.Fatal("invalid id was stored")
	}
	if _, err := store.Get("bad id"); !errors.Is(err, ErrInvalidID) {
		t.Fatalf("get invalid = %v, want ErrInvalidID", err)
	}
	// Valid path unaffected.
	store.Create("abcd1234", "alice")
	if _, err := store.Get("abcd1234"); err != nil {
		t.Fatalf("valid create+get: %v", err)
	}

	handler := sessionHandler(store)
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("POST", "/session?id=bad%20id&user=u", nil))
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("POST invalid status = %d, want 400", rec.Code)
	}
	rec = httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/session?id=bad%20id", nil))
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("GET invalid status = %d, want 400", rec.Code)
	}
	rec = httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/session?id=abcd1234", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("GET valid status = %d, want 200", rec.Code)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_valid_test.go ; exit $rc

